package main

import (
	"encoding/json"
	"net/http"
	"net/http/httptest"
	"net/url"
	"os"
	"path/filepath"
	"strings"
	"testing"
)

// The page shows a chosen file's text before and after it is chosen. The endpoint serves only what the picker could offer:
// a hand-written text file inside the repo, never a hidden path, a folder, a generated file or something that is not text.
func TestHandleFile(t *testing.T) {
	dir, outside := t.TempDir(), t.TempDir()
	put := func(base, rel string, body []byte) {
		p := filepath.Join(base, rel)
		if err := os.MkdirAll(filepath.Dir(p), 0o755); err != nil {
			t.Fatal(err)
		}
		if err := os.WriteFile(p, body, 0o644); err != nil {
			t.Fatal(err)
		}
	}
	put(dir, "extras/web.caddy", []byte("encode gzip\nheader X 1\n"))
	put(dir, "extras/big.caddy", []byte(strings.Repeat("# line\n", fileViewLimit/7+100)))
	put(dir, "extras/bin.dat", []byte{0x00, 0x01, 0x02})
	put(dir, "extras/latin1.caddy", []byte{'a', 0xff, 'b'})
	put(dir, "edge/caddy/data/gen.caddy", []byte("# GENERATED by hemma — do not edit\n"))
	put(dir, ".git/config", []byte("secret\n"))
	put(dir, ".env", []byte("TOKEN=x\n"))
	put(outside, "secret.caddy", []byte("# not in the repo\n"))
	if err := os.Symlink(filepath.Join(outside, "secret.caddy"), filepath.Join(dir, "extras", "link.caddy")); err != nil {
		t.Fatal(err)
	}
	s := &server{repo: dir}

	get := func(path string) (int, map[string]any) {
		r := httptest.NewRequest(http.MethodGet, "/api/file?path="+url.QueryEscape(path), nil)
		w := httptest.NewRecorder()
		s.handleFile(w, r)
		var out map[string]any
		_ = json.Unmarshal(w.Body.Bytes(), &out)
		return w.Code, out
	}

	if code, out := get("extras/web.caddy"); code != 200 || out["content"] != "encode gzip\nheader X 1\n" || out["truncated"] != false {
		t.Errorf("a normal file: %d %v", code, out)
	}
	if code, out := get("extras/big.caddy"); code != 200 || out["truncated"] != true || len(out["content"].(string)) > fileViewLimit {
		t.Errorf("a long file must be cut and say so: %d truncated=%v", code, out["truncated"])
	}
	for _, c := range []struct{ name, path string }{
		{"a folder", "extras"},
		{"missing", "extras/nope.caddy"},
		{"a hidden folder", ".git/config"},
		{"a dotfile", ".env"},
		{"outside the repo", "../secret.caddy"},
		{"absolute", "/etc/hosts"},
		{"a symlink that leaves the repo", "extras/link.caddy"},
		{"generated by hemma", "edge/caddy/data/gen.caddy"},
		{"empty", ""},
	} {
		if code, out := get(c.path); code == 200 {
			t.Errorf("%s (%q) must be refused, got 200 %v", c.name, c.path, out)
		}
	}
	for _, c := range []struct{ name, path string }{{"binary", "extras/bin.dat"}, {"not UTF-8", "extras/latin1.caddy"}} {
		if code, _ := get(c.path); code != 415 {
			t.Errorf("%s (%q): want 415, got %d", c.name, c.path, code)
		}
	}
}
